export class RejectedError extends Error {
  constructor(message, reason) {
    super(message || 'Request rejected');
    this.name = 'RejectedError';
    this.code = 'Rejected';
    if (reason) this.reason = reason;
  }
}

export class NotLeaderError extends RejectedError {
  constructor(term, leaderId, forwardHint) {
    super('Not leader', 'NotLeader');
    this.name = 'NotLeaderError';
    this.code = 'NotLeader';
    this.term = typeof term === 'number' ? term : Number(term || 0);
    if (leaderId != null) this.leaderId = String(leaderId);
    if (forwardHint) this.forwardHint = forwardHint;
  }
}

export class TimeoutError extends Error {
  constructor(message = 'Operation timed out') {
    super(message);
    this.name = 'TimeoutError';
    this.code = 'Timeout';
  }
}
